window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"q3xsQIou-t0","speaker":"José Manuel Restrepo","role":"Vice President","country":"Colombia","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=q3xsQIou-t0","date":"20260924","title":"🇨🇴 Colombia - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1302,"words":2604,"counts":{"claims":31,"promises":9,"attacks":1},"topics":[{"topic":"UN reform","share":0.2511,"seconds":327},{"topic":"Terrorism","share":0.1082,"seconds":141},{"topic":"Colombia economy","share":0.1037,"seconds":135},{"topic":"Colombia development","share":0.0953,"seconds":124},{"topic":"Colombia disaster","share":0.0943,"seconds":123},{"topic":"Colombia investment","share":0.0541,"seconds":70},{"topic":"Colombia technology","share":0.051,"seconds":66},{"topic":"Colombia security","share":0.0508,"seconds":66},{"topic":"Venezuela transition","share":0.0499,"seconds":65},{"topic":"Colombia drugs","share":0.0478,"seconds":62},{"topic":"Colombia governance","share":0.0471,"seconds":61},{"topic":"Colombia reconstruction","share":0.0466,"seconds":61}],"timeline":[[3,74,null],[75,154,null],[156,219,"Colombia disaster"],[222,282,"Colombia disaster"],[284,345,"Colombia governance"],[346,413,"Colombia security"],[414,476,"Colombia drugs"],[477,544,"Colombia economy"],[546,612,"Colombia technology"],[613,673,"Colombia development"],[673,741,"Colombia economy"],[742,803,"UN reform"],[805,872,"UN reform"],[873,938,"Venezuela transition"],[938,1015,"UN reform"],[1016,1078,"UN reform"],[1079,1156,"Terrorism"],[1157,1221,"Terrorism"],[1222,1283,"UN reform"],[1285,1355,"Colombia investment"],[1356,1417,"Colombia reconstruction"],[1419,1483,"Colombia development"],[1486,1489,null]],"stances":{"Colombia disaster":"José Manuel Restrepo states that the government prioritized saving human lives above all other administrative tasks during the disaster response.","Colombia governance":"José Manuel Restrepo states that his government is committed to restoring public trust in the state and law as a prerequisite for national prosperity.","Colombia security":"José Manuel Restrepo states that his government has instructed security forces to regain territorial control and confront terrorist structures.","Colombia drugs":"José Manuel Restrepo states that illicit drug production in Colombia is a transnational criminal enterprise requiring both state force and international cooperation to combat.","Colombia economy":"José Manuel Restrepo argues that security alone is insufficient and emphasizes the need to create economic foundations, production capacity, and investment opportunities for Colombia's growth.","Colombia technology":"José Manuel Restrepo states that Colombia aims to actively participate in the technological transformation by training young people in emerging fields and providing opportunities for citizens to build their own lives rather than relying on state intervention.","Colombia development":"José Manuel Restrepo describes a vision for Colombia where security, investment, and education drive economic growth and improved living conditions across various regions.","UN reform":"José Manuel Restrepo states that his criticism of the United Nations is based on doctrinal reasons and a desire to ensure the organization effectively addresses its founding problems, rather than hostility.","Venezuela transition":"José Manuel Restrepo expresses trust in a democratic transition for Venezuela and emphasizes the need for consistent human rights defense.","Terrorism":"José Manuel Restrepo argues that the international community must establish a universally agreed legal definition of terrorism to resolve current legal uncertainties and facilitate effective cooperation.","Colombia investment":"José Manuel Restrepo states that foreign policy aims to create jobs, attract investment, and open markets for Colombians while inviting the world to invest in Colombia.","Colombia reconstruction":"José Manuel Restrepo states that Colombia is taking primary responsibility for its own rebuilding while seeking international partners for trade and security."},"claims":[{"t":156,"quote":"Hundreds of Colombians lost their lives. 4,500 were injured and more than 452,000 people were affected.","topic":"Colombia disaster","kind":"number"},{"t":170,"quote":"36,000 homes were totally destroyed.","topic":"Colombia disaster","kind":"number"},{"t":255,"quote":"The earthquake claimed the lives of many of our fellow Colombians and destroyed thousands of homes and buildings and much infrastructure.","topic":"Colombia disaster","kind":"fact"},{"t":289,"quote":"On the 7th of August, I took over a country that had begun to lose something far more difficult to rebuild than a road or a building. That is trust.","topic":"Colombia governance","kind":"fact"},{"t":316,"quote":"No country, no country can prosper when its people cease to trust in it.","topic":"Colombia governance","kind":"fact"},{"t":363,"quote":"A rural farmer having to ask permission from a terrorist group to work on his land. A shopkeeper having to hand over part of the fruits of his labor to A mother increasingly gripped by fear every time their child goes out to play in the park.","topic":"Colombia security","kind":"fact"},{"t":444,"quote":"The illicit drugs produced in Colombia don't end up in Colombia. Drugs is a transnational criminal enterprise. Its roots cross borders. Its money moves through international financial systems. And its networks operate across numerous","topic":"Colombia drugs","kind":"fact"},{"t":523,"quote":"In our miracle nation, we want an idea to be able to become a business, a business to create jobs and for jobs to become well-being for our people.","topic":"Colombia economy","kind":"fact"},{"t":546,"quote":"It's a country with access to two oceans, productive land, energy resources, enormous biodiversity, an excellent geographical position, and a government that champions private enterprise.","topic":"Colombia technology","kind":"fact"},{"t":575,"quote":"We want to train young people for super intelligence, for robotics, for data science, for agro industry, for engineering, and for the new economy.","topic":"Colombia technology","kind":"fact"},{"t":631,"quote":"It is a school teacher in Mos Bolivar teaching with the tools of the 21st century.","topic":"Colombia development","kind":"fact"},{"t":639,"quote":"It is a rural farmer in Ubate Kundina Mara who can now sew, sell and prosper thanks to his work.","topic":"Colombia development","kind":"fact"},{"t":648,"quote":"It's uh a young woman in Pastor Nadinho preparing to be a part of f the future industries.","topic":"Colombia development","kind":"fact"},{"t":673,"quote":"And I want Colombia to once again enjoy strong growth. That growth should lead to a job for a young person, a home for a family, timely access to medicines, a harvest that finds a market, and Colombians who, thanks to their own efforts and dedication, can escape poverty.","topic":"Colombia economy","kind":"fact"},{"t":711,"quote":"Over the last few weeks, we have seen this very tangibly when friendly countries and international organizations came to our aid following the earthquake.","topic":"Colombia economy","kind":"fact"},{"t":790,"quote":"This organization was born to maintain international peace and to foster friendly relations among nations and to promote cooperation in resolving the major common problems.","topic":"UN reform","kind":"fact"},{"t":805,"quote":"Eight decades on the question can cannot be whether those purposes remain valid. Of course they do.","topic":"UN reform","kind":"fact"},{"t":850,"quote":"Colombia defends human rights and will continue to do so.","topic":"UN reform","kind":"self_credit"},{"t":918,"quote":"In that connection we trust in a democratic transition in Venezuela, a swift, safe, farreaching transition.","topic":"Venezuela transition","kind":"fact"},{"t":950,"quote":"I'm talking about a concept according to which nation, sovereignty, distinct identities, traditions and the values of peoples are obstacles that gradually give way to increasing political and cultural uniformity decided by super national bodies.","topic":"UN reform","kind":"fact"},{"t":1016,"quote":"The UN80 initiative has placed on the table issues of duplication, fragmentation, administrative burden, and the way mandates function as part of an effort to make the United Nations more efficient and more effective.","topic":"UN reform","kind":"fact"},{"t":1070,"quote":"No human institution is perfect. All can be improved, perfected and the United Nations is no exception.","topic":"UN reform","kind":"fact"},{"t":1091,"quote":"Since 1963, the international community has developed 19 universal legal instruments aimed at preventing different terrorist acts.","topic":"Terrorism","kind":"number"},{"t":1114,"quote":"The UN Office of Counterterrorism itself has recently flagged that the lack of a universally agreed definition beggets legal uncertainty, discrepancies among national laws, and causes difficulties in international cooperation.","topic":"Terrorism","kind":"fact"},{"t":1192,"quote":"The United Nations has repeatedly reaffirmed that terrorism in all of its forms and manifestations represents one of the most serious threats to international peace","topic":"Terrorism","kind":"fact"},{"t":1222,"quote":"We need better judicial cooperation, effective tracing, freezing, seizing instruments um for assets related to terrorist financing.","topic":"UN reform","kind":"fact"},{"t":1232,"quote":"And we need closer cooperation to deal with networks that operate simultaneously across different countries.","topic":"UN reform","kind":"fact"},{"t":1285,"quote":"Drugs trafficking, terrorism, transnational organized crime, and illicit economies are precisely those my government's foreign policy is guided by national interest","topic":"Colombia investment","kind":"fact"},{"t":1347,"quote":"I am working tirelessly to build you a nation that is to build a nation that is safer, more prosperous, and with more opportunities for its people","topic":"Colombia investment","kind":"self_credit"},{"t":1366,"quote":"rebuilding our country, restoring security, growing the economy, protecting our institutions, and giving opportunities back to millions of people are first and foremost responsibilities that fall to","topic":"Colombia reconstruction","kind":"fact"},{"t":1435,"quote":"I want within a few years when the world looks again at my country, I want them to see a nation that is safer, more prosperous, more wellrespected, and above all far more confident in its own abilities.","topic":"Colombia development","kind":"fact"}],"promises":[{"t":324,"quote":"That's why the government that I lead has tasked itself with taking up every possible decision to enable Colombia to believe in itself again and to ensure that the world can believe in Colombia again.","topic":"Colombia governance","kind":"promise"},{"t":390,"quote":"I gave the security forces one clear instruction to regain territorial control to fully restore the state's authority and to confront the structures using terrorism.","topic":"Colombia security","kind":"promise"},{"t":408,"quote":"My government is determined to do away with euphemisms.","topic":"Colombia security","kind":"promise"},{"t":465,"quote":"I will do everything necessary to combat that scourge.","topic":"Colombia drugs","kind":"promise"},{"t":487,"quote":"My administration is therefore also focused on ensuring that Colombia grows again.","topic":"Colombia economy","kind":"promise"},{"t":519,"quote":"What they have to do is lay the foundations for it to occur.","topic":"Colombia economy","kind":"promise"},{"t":1239,"quote":"Colombia stands ready to participate actively in that discussion.","topic":"UN reform","kind":"promise"},{"t":1266,"quote":"That is the sort of multilateralism that Colombia is ready to defend.","topic":"UN reform","kind":"promise"},{"t":1345,"quote":"I can assure you that I am working tirelessly to build you a nation that is to build a nation that is safer, more prosperous, and with more opportunities for its people","topic":"Colombia investment","kind":"promise"}],"attacks":[{"t":864,"quote":"I categorically reject human rights being used as a banner raised against some and lowered against others.","topic":"UN reform","target":"Human Rights Organizations"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":null,"text":"The assembly will address by his excellency Jose Emmanuel Ripo, vice president of the Republic of Colombia. I request protocol to escort his excellency and invite him to address the Mr. Secretary General, Mr. the Vice President of the General Assembly, heads of state and government, excellencies, ambassadors, ladies and gentlemen, I appear today before this assembly, representing the President of the Republic of Colombia, Aardo de Laspa, who has asked me to be here on his behalf and bring before you a message written by him."},{"t":75,"topic":null,"text":"From this moment on, what you will hear are the words of the president of the Republic of Colombia. &gt;&gt; I have asked the vice president of the republic, Jose Manuel Estreo, to read this message on my behalf. I have done so because I assured the Colombian people that I would not leave the country during the four years of my term and I am keeping that promise. 47 days ago, a new government took office in Colombia. 3 days later, at 7:34 a.m., the Earth shook a 7.4 4 magnitude earthquake struck my In a matter of seconds, homes, hospitals, schools, roads, and bridges had been totally destroyed or severely The Colombian Geological Service confirmed that this was the strongest magnitude earthquake recorded in Colombia so far this century."},{"t":156,"topic":"Colombia disaster","text":"Hundreds of Colombians lost their lives. 4,500 were injured and more than 452,000 people were affected. 36,000 homes were totally destroyed. They represented the life savings assets of these people. The government that had barely started its work was forced to confront one of the greatest natural disasters in our recent history. There was no time to ask whether we were ready. We had to act and we did so from the very outset. I gave one unequivocal instruction. We had to save human lives. There was time for everything else. Appointments to posts could wait. Meetings could wait. But my fellow fellow Colombians trapped underneath the rubble could not."},{"t":222,"topic":"Colombia disaster","text":"The government deployed to the affected areas alongside the security forces, emergency services, volunteers and rescue workers. And from the very beginning, we started receiving the generous assistance from friendly countries and international such as all of you. And today from this rostrm I wish to express the profound and sincere gratitude of the Colombian people to all of you. The earthquake claimed the lives of many of our fellow Colombians and destroyed thousands of homes and buildings and much infrastructure. But it also reminded us once again of something that Colombians are very familiar with. We might fall. We might suffer. We might weep, but what we cannot and what we do not know how to do is give up. But I'm not only going to talk to you about this tragedy."},{"t":284,"topic":"Colombia governance","text":"I want to refer to what Colombia decided to do in its aftermath. On the 7th of August, I took over a country that had begun to lose something far more difficult to rebuild than a road or a building. That is trust. Trust in the law that should protect our citizens. Trust that working, studying, and doing things well are worthwhile. Trust in a state that lives up to its duty. No country, no country can prosper when its people cease to trust in it. That's why the government that I lead has tasked itself with taking up every possible decision to enable Colombia to believe in itself again and to ensure that the world can believe in Colombia again. And I call that overarching purpose the Patria Magro, the miracle nation."},{"t":346,"topic":"Colombia security","text":"The first step is a basic one, restoring For far too long, Colombians have had to live alongside situations that no society should accept as normal. A rural farmer having to ask permission from a terrorist group to work on his land. A shopkeeper having to hand over part of the fruits of his labor to A mother increasingly gripped by fear every time their child goes out to play in the park. that is not and it cannot become the norm. Conse consequently, from the very beginning of my government, I gave the security forces one clear instruction to regain territorial control to fully restore the state's authority and to confront the structures using terrorism. My government is determined to do away with euphemisms."},{"t":414,"topic":"Colombia drugs","text":"Organizations that murder, that kidnap, that use explosives, that recruit children, and that deliberately resort to terror to subjugate a society are terrorist That is what we call them. And we are facing up to them with the full legitimate force of the state within the constitution and within the law. But there is another reality that is very often overlooked. The illicit drugs produced in Colombia don't end up in Colombia. Drugs is a transnational criminal enterprise. Its roots cross borders. Its money moves through international financial systems. And its networks operate across numerous I will do everything necessary to combat that scourge. But a transnational threat requires the international community to play its part as well."},{"t":477,"topic":"Colombia economy","text":"Security, while essential, is not enough. A territory that provides no opportunities, remains My administration is therefore also focused on ensuring that Colombia grows again. For years, we have discussed how to better dist distribute what we have. That is a legitimate necessary discussion, but it's absolutely not enough. We also need to ask ourselves how are we going to produce more? In the end, governments can't decree economic growth. What they have to do is lay the foundations for it to occur. In our miracle nation, we want an idea to be able to become a business, a business to create jobs and for jobs to become well-being for our people. To those of you anywhere else in the world who are wondering where to invest, I would like to invite you to look at Colombia."},{"t":546,"topic":"Colombia technology","text":"It's a country with access to two oceans, productive land, energy resources, enormous biodiversity, an excellent geographical position, and a government that champions private enterprise. But above all, look at our does not want to watch the technological transformation of our time from the sidelines. We want to be a part of it. We want to train young people for super intelligence, for robotics, for data science, for agro industry, for engineering, and for the new economy. Millions of Colombians are not asking the state to sort out their lives. They're asking the state to give them the opportunity to build those lives. And that is what gives meaning to what I have called the miracle nation. This isn't the name of a government, nor is it a naive promise that our problems will just disappear."},{"t":613,"topic":"Colombia development","text":"No, that's not it. This is the country that we're going to build. It's a country where security allows us to reclaim the territories threatened by terrorism, where trust attracts investment, where investment creates jobs, and where growth leads to better living conditions. It is a school teacher in Mos Bolivar teaching with the tools of the 21st century. It is a rural farmer in Ubate Kundina Mara who can now sew, sell and prosper thanks to his work. It's uh a young woman in Pastor Nadinho preparing to be a part of f the future industries. This is the miracle nation that we've already started to build. I'm well aware that 47 days is far too little time to change a country, but it is enough time to change the course of a country."},{"t":673,"topic":"Colombia economy","text":"And I want Colombia to once again enjoy strong growth. That growth should lead to a job for a young person, a home for a family, timely access to medicines, a harvest that finds a market, and Colombians who, thanks to their own efforts and dedication, can escape poverty. This is our miracle economy, an economy that grows so that people can grow with relationship with the world is also a part of this purpose. Over the last few weeks, we have seen this very tangibly when friendly countries and international organizations came to our aid following the earthquake. This solidarity makes full sense when it reaches people, when it solves problems, and when it produces results. And it is precisely because I recognize the value of that corporation that today I want to speak frankly about the UN."},{"t":742,"topic":"UN reform","text":"I've been critical about this of this organization. I was critical of it before I became president and it would be inconsistent to address this assembly today and conceal my attempt to consil my convictions. This criticism isn't born out of whim or hostility towards the United Nations. It's based in political, institutional, doctrinal I believe in the UN as an organization and it is precisely for that reason that I believe it's legitimate to ask whether the institutions that we've been building are effectively responding to the problems that that it was created to address. The charter itself is very clear here. This organization was born to maintain international peace and to foster friendly relations among nations and to promote cooperation in resolving the major common problems."},{"t":805,"topic":"UN reform","text":"Eight decades on the question can cannot be whether those purposes remain valid. Of course they do. The questions have completely changed though. Is the UN fulfilling those purposes with the effectiveness demanded by today's world? Are there bureaucratic structures that have become excessively cumbersome? Are we dedicating too many resources, too much energy to administering procedures and or too little to resolving problems? Are we measuring our results rigorously Another matter that I wish to address is human rights. Colombia defends human rights and will continue to do so. But my country believes that protecting human rights loses credibility when it becomes subjected to political calculation. I categorically reject human rights being used as a banner raised against some and lowered against others."},{"t":873,"topic":"Venezuela transition","text":"Nor can human rights become an instrument rewarding friends, punishing adversaries, or worse still, remaining silent in line with the political circumstances of the time. Our duty is to prevent politics from weakening the defense of human rights. If we want the system to be respected, it needs to be serious, consistent, and equally demanding on all of us. My country is consistent and therefore we want to ensure that we have a credible defense of human rights and in this just as in so many other areas the United Nations still has some room for improvement. In that connection we trust in a democratic transition in Venezuela, a swift, safe, farreaching transition. There's another doctrinal concern that I wish to raise just as honestly, Allow me to begin by clarifying what I mean by that."},{"t":938,"topic":"UN reform","text":"I'm not talking about international trade or cooperation among states, nor am I talking about a humanity that shares common problems and responsibilities. All of those things are absolutely necessary. I'm talking about a concept according to which nation, sovereignty, distinct identities, traditions and the values of peoples are obstacles that gradually give way to increasing political and cultural uniformity decided by super national bodies. I don't share in that doctrine which I consider perverse and harmful. For me, multilateralism isn't about dissolving nations, but rather about facilitating cooperation among Loving one's homeland isn't compatible with respecting others. Defending history, culture, values, and traditions doesn't mean disparaging those of another. International cooperation is richer when those who sit around this table know who they are, where they come from, and what the people in whose name they speak Several of the questions that I've asked are not unfamiliar to this organization."},{"t":1016,"topic":"UN reform","text":"The UN80 initiative has placed on the table issues of duplication, fragmentation, administrative burden, and the way mandates function as part of an effort to make the United Nations more efficient and more effective. President, Secretary General, heads of state and government excellencies, acknowledging an institution's imperfections doesn't mean overlooking its value. But on the contrary, it might be a way of strengthening it. It has never been my style to hide behind political correctness or to tell my interlocutors what I imagine they want to hear. I'm not looking to please anyone, but rather to set out the position of the Republic of Colombia respectfully, cordially, and clearly. No human institution is perfect. All can be improved, perfected and the United Nations is no exception."},{"t":1079,"topic":"Terrorism","text":"There is one specific area that Colombia wishes to reflect on further. That is the international fight against terrorism. This organization has done significant work here. Since 1963, the international community has developed 19 universal legal instruments aimed at preventing different terrorist acts. However, after decades of discussion, there is still no legal definition of terrorism that is universally agreed by member states. The UN Office of Counterterrorism itself has recently flagged that the lack of a universally agreed definition beggets legal uncertainty, discrepancies among national laws, and causes difficulties in international cooperation. The Republic of Colombia believes that the time has come to move ahead. We need a common international def definition that is sufficiently clear and precise, compatible with international law and fundamental safeguards, but also useful enough so that states can cooperate effectively in combating acts of terrorism."},{"t":1157,"topic":"Terrorism","text":"A serious definition should avoid two extremes. On the one hand, a political disagreement being arbitrarily characterized as terrorism. And on the other hand, allowing an organization to hide murders, kidnappings, bombings, or deliberate attacks against civilians behind a political label in order to evade the legal consequences of its actions. Terrorism must be condemned regardless of the perpetrator, where it is committed, or the cause they invoke. The United Nations has repeatedly reaffirmed that terrorism in all of its forms and manifestations represents one of the most serious threats to international peace and a better definition is not enough. States need better tools to combat this We need faster mechanisms for exchanging information and intelligence."},{"t":1222,"topic":"UN reform","text":"We need better judicial cooperation, effective tracing, freezing, seizing instruments um for assets related to terrorist financing. And we need closer cooperation to deal with networks that operate simultaneously across different countries. Colombia stands ready to participate actively in that discussion. My country wants to see United Nations where the effectiveness is measured less by the volume of documents it produces and far more by the results that it A UN that is less inclined to multiply processes and more determined to translate international cooperation into concrete action. That is the sort of multilateralism that Colombia is ready to defend. One that respects the sovereign equality of states, as the charter itself provides, but one that is also capable of acting effectively when threats recognize no borders."},{"t":1285,"topic":"Colombia investment","text":"Drugs trafficking, terrorism, transnational organized crime, and illicit economies are precisely those my government's foreign policy is guided by national interest, by the defense of our sovereignty and by the pursuit of That national interest I referred to also has a specific objective that is ensuring the prosperity of our people. Foreign policy should serve to create jobs, to attract investment and technology, to open markets, and to create opportunities for Colombians. With that goal in mind, I wish to extend an invitation to the world. Come to Invest in Colombia. Grow and prosper with Colombia. Believe in Colombia. I don't promise you a perfect country, but I can assure you that I am working tirelessly to build you a nation that is to build a nation that is safer, more prosperous, and with more opportunities for its people."},{"t":1356,"topic":"Colombia reconstruction","text":"Colombia does not come before the world today to ask others to do for us what it is our responsibility to do for ourselves. rebuilding our country, restoring security, growing the economy, protecting our institutions, and giving opportunities back to millions of people are first and foremost responsibilities that fall to But we also know that no nation can turn its back on the world. We need partners and friends with whom we can trade, invest, exchange knowledge and address common threats. That is the Colombia that I present to you today. A country that is well aware of its difficulties, but also of its enormous potential. A country that doesn't try to hide its problems, but rather to confront them. A country that is getting back on its feet and knows where it wants to go."},{"t":1419,"topic":"Colombia development","text":"To the nations represented here, I extend my hand respectfully and through Colombia wants to work with you on everything that we can build together. I want within a few years when the world looks again at my country, I want them to see a nation that is safer, more prosperous, more wellrespected, and above all far more confident in its own abilities. And if that is the Colombia that the world sees, there'll be no need to explain what I meant when I spoke of the Patria Magro, the miracle nation. Thank you very much. On behalf of the assembly, I wish to thank the vice president of the Republic of Colombia."},{"t":1486,"topic":null,"text":"The assembly will hear an address by his"}],"compare":[{"topic":"UN & its reform","share":0.2511,"mean":0.2045,"rank":66,"others":170},{"topic":"Terrorism","share":0.1082,"mean":0.0023,"rank":2,"others":6},{"topic":"Colombia","share":0.0508,"mean":0.0,"rank":1,"others":0},{"topic":"Venezuela","share":0.0499,"mean":0.0049,"rank":10,"others":11}]};
